ALTER SESSION SET CURRENT_SCHEMA = LEHZ;

-- COMUNAS: resolver ID_REGION por nombre, nunca por ID fijo.
-- Si hay regiones duplicadas por nombre, MIN elige un ID existente.

COMMIT;

-- Verificar cantidad de comunas por region
SELECT R.ID_REGION, R.NOMBRE_REGION, COUNT(C.ID_COMUNA) AS TOTAL_COMUNAS FROM LEHZ_REGION R LEFT JOIN LEHZ_COMUNA C ON C.ID_REGION = R.ID_REGION GROUP BY R.ID_REGION, R.NOMBRE_REGION ORDER BY R.ID_REGION;
